function checkForPrimes(arr) {
  for (const num of arr) {
    if (isPrime(num)) {
      console.log(`Found prime number: ${num}`);
      return; // stop checking once we've found a prime
    }
  }
}

function isPrime(n) {
  if (n <= 1) return false; // 0 and 1 are not prime
  for (let i = 2; i * i <= n; i++) {
    if (n % i === 0) return false; // if divisible by any other number besides 1 and itself, it's not prime
  }
  return true; // if no divisors found, it's a prime number
}
```
